// The highest true rate the data still allows, at 95% confidence (z = 1.96).
export const wilsonUpper = (bad: number, n: number, z = 1.96): number => {
  if (n === 0) return 1;
  const p = bad / n;
  const z2 = z * z;
  const centre = p + z2 / (2 * n);
  const spread = z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n));
  return (centre + spread) / (1 + z2 / n);
};

