import { writeFileSync } from "node:fs";

type Row = { allFixed: boolean; verdict: "fulfilled" | "unfulfilled"; sure: boolean; reflagged: boolean };
const rows = (n: number, row: Row): Row[] => Array.from({ length: n }, () => row);
const skip: Row = { allFixed: true, verdict: "fulfilled", sure: true, reflagged: false };
const wrong: Row = { ...skip, reflagged: true };
const unsure: Row = { allFixed: true, verdict: "fulfilled", sure: false, reflagged: false };
const open: Row = { allFixed: false, verdict: "unfulfilled", sure: true, reflagged: false };

const write = (file: string, data: Row[]) =>
  writeFileSync(file, data.map((r) => JSON.stringify(r)).join("\n") + "\n");

write("week-1.jsonl", [...rows(60, skip), ...rows(40, unsure), ...rows(50, open)]);
write("week-4.jsonl", [...rows(299, skip), ...rows(1, wrong), ...rows(150, unsure), ...rows(200, open)]);
write("noisy.jsonl", [...rows(291, skip), ...rows(9, wrong), ...rows(150, unsure), ...rows(200, open)]);
console.log("wrote week-1.jsonl, week-4.jsonl, noisy.jsonl");
EOF
