import { readFileSync } from "node:fs";
import { wilsonUpper } from "./wilson.ts";

type Pair = { allFixed: boolean; verdict: "fulfilled" | "unfulfilled"; sure: boolean; reflagged: boolean };

export const goLive = (pairs: Pair[]) => {
  const skips = pairs.filter((p) => p.verdict === "fulfilled" && p.sure);
  const wrong = skips.filter((p) => p.reflagged).length;
  const allFixed = pairs.filter((p) => p.allFixed);
  const upper = wilsonUpper(wrong, skips.length);
  const skipRate = allFixed.length === 0 ? 0 : allFixed.filter((p) => skips.includes(p)).length / allFixed.length;
  return { sure: skips.length, wrong, upper, skipRate, live: upper <= 0.02 && skipRate >= 0.4 };
};

const file = process.argv[2] ?? "week-1.jsonl";
const pairs: Pair[] = readFileSync(file, "utf8").trim().split("\n").map((line) => JSON.parse(line));
const r = goLive(pairs);
const pct = (x: number) => `${(x * 100).toFixed(1)}%`;
console.log(`${file}: ${r.wrong} wrong of ${r.sure} sure skips, could be up to ${pct(r.upper)}; skip rate ${pct(r.skipRate)}`);
console.log(r.live ? "GO LIVE: set observe to false" : "STAY IN OBSERVE MODE");
EOF
for f in week-1 week-4 noisy; do node go-live.ts $f.jsonl; done

